ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-attention-20261002';DATA=ROOT/'data/btc-attention-20261002'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');fore=read(RUN/'forecast-summary.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');assert len(s)==v['accounts']==48 and rep['all_bytes_equal'] and not sel['passed'];rows=[];base=[];annual=[];cost=[];ci=[]
 for n in ('AT_INFO','AT_PRICE','AT_RAW','AT_INV'):
  a=s['main-'+n+'-base']['metrics'];b=s['recent-'+n+'-base']['metrics'];base.append([n+(' · 기본' if n=='AT_INFO' else ' · 대조'),f"{a['return_pct']:+.2f}",f"{a['max_drawdown_pct']:.2f}",f"{b['return_pct']:+.2f}",f"{b['max_drawdown_pct']:.2f}",str(a['round_trips'])+' / '+str(b['round_trips'])])
  for p in ('main','recent'):
   key=p+'-'+n+'-base';e=s[key];m=e['metrics'];d=diag[key+'.json.gz']['sides'];annual.append([n,p,*[f"{e['annual'][y]['return_pct']:+.2f}" if y in e['annual'] else '해당 없음' for y in ('2022','2023','2024','2025','2026')]]);cost.append([n,p,f"{m['gross_pnl']:+.2f}",f"{m['fees']+m['impact']:.2f}",f"{m['funding']:+.2f}",f"{m['mean_exposure']*100:.2f}",f"{m['realized_vol_pct']:.2f}",f"{d['BS']['net']:+.2f}",f"{d['BP']['net']:+.2f}"])
   for c in ('E_SPOT','AT_PRICE','AT_RAW'):
    q=unc[p+'-'+n]['vs_'+c][1]['ci95'];ci.append([n,p,c,f'{q[0]:+.5f} ~ {q[1]:+.5f}'])
 for key,e in s.items():
  p,n,c=key.split('-');m=e['metrics'];rows.append({'strategy':n,'period':p,'scenario':c,**{k:m[k] for k in ('return_pct','max_drawdown_pct','realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure')}})
 evidence={'build':'1002a1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'forecast':fore,'uncertainty':unc,'diagnostics':diag,'information_age':read(RUN/'information-age.json'),'source_audit':read(DATA/'audit.json'),'scope':'BTC-only development; pageview requests are not unique investors or causal demand; no accepted strategy'};(DOWN/'btc-attention-evidence.json').write_bytes(canonical(evidence))
 with (DOWN/'btc-attention-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 with zipfile.ZipFile(DOWN/'btc-attention-evidence.zip','w',compression=zipfile.ZIP_STORED) as z:
  files=[(p,'run/'+p.name) for p in sorted(RUN.iterdir()) if p.is_file()]
  files += [(DATA/n,'attention/'+n) for n in ('wikipedia-bitcoin.json','source.json','audit.json','cross-window-audit.json','cross-2020.json','cross-2022.json','cross-2026.json')]
  for n in ('btc_attention_study.py','test_btc_attention_study.py','verify_btc_attention_study.py','reproduce_btc_attention_study.py','btc_target_ledger.py','btc_cot_study.py','btc_persistence_study.py'):files.append((ROOT/'tools'/n,'source/'+n))
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,2,0,0,0)),p.read_bytes())
  z.writestr(zipfile.ZipInfo('DATA-SOURCES.txt',(2026,10,2,0,0,0)),'Wikimedia official aggregated Bitcoin page views only: https://wikimedia.org/api/rest_v1/metrics/pageviews/per-article/en.wikipedia.org/all-access/user/Bitcoin/daily/2020010100/2026083100 . Aggregate page requests are not unique investors; no IP/session/private data acquired. Current historical snapshot and 21-day same-provider cross-window check, not first-publication vintages. Official Binance BTC price/funding archives and common dependencies are separate reproduction inputs.\n')
 html='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self';script-src 'none';style-src 'self';img-src 'self' data:;connect-src 'none';object-src 'none';base-uri 'none';form-action 'none'"><title>BTC 관심도 추가정보 검증</title><link rel="icon" href="assets/icon.svg"><link rel="stylesheet" href="assets/btc-continuation.css"></head><body><a class="skip" href="#results">결과로 이동</a><header><a href="./">BTC RESEARCH</a><nav><a href="btc-web-research.html">전체 연구 기록</a><a href="btc-residual-research.html">앞선 캐리 검증</a><a href="#downloads">검증 자료</a></nav></header><main><p class="eyebrow">BTC-ONLY · BUILD1002a1</p><h1>읽는 사람이 늘어도,<br>수익 정보가 더해지지는 않았습니다.</h1><p class="lead">BTC Wikipedia 정보수요가 가격 충격 이상의 정보를 주는지 검증했습니다. 사전 고정 후보는 주·최근 모두 손실로 기각됐습니다.</p><div class="facts"><article><b>48</b><span>조건별 가상계좌</span></article><article><b>기각</b><span>AT_INFO 기본 후보</span></article><article><b>2,435</b><span>공식 BTC 조회수 일별 관측</span></article></div><p class="boundary">2022–2025와2026.01–08은 이미 본 개발 자료입니다. 미사용 OOS·실전 성과·최적 전략이 아닙니다. 대조군을 결과 뒤 기본 후보로 교체하지 않았습니다.</p><section id="results"><h2>기본과 모든 대조군</h2><p>각1,000USDT, 수익·최대낙폭(DD)은 %. 조회수는투자자수나매수의향이아닙니다.</p>'''+table(['규칙','4년 수익','4년 DD','최근 수익','최근 DD','주/최근 보유구간'],base,'base-results')+'''<p>AT_INFO는 주−13.16%·DD15.21%, 최근−3.24%·DD5.62%입니다. 사전 수익 기준(주 E_SPOT +52.84%, 최근 E_LS +4.63%)에 미달했습니다. 반대 대조의 일부 수익이나 적은 거래를 성공으로 포장하지 않았습니다.</p></section><section><h2>상충하는 근거를 그대로 기록했습니다</h2><p>2014년 논문은 검색 급증 뒤 가격 하락을,2021년 논문은 일부 주간수익 예측 개선을 보였습니다.2015년 논문은 검색량 대신감성·양극화·거래량을선택했습니다. 효과의부호·시대·데이터정의가같지않아어느하나를그대로거래성과로받아들이지않았습니다.</p><p>현재 공식Wikipedia API의영어Bitcoin문서 user조회수를사용했습니다. 과거legacy나GoogleTrends의전체정규화지표와다릅니다. 같은요일의직전8주로그조회평균대비증가를측정하고조회당일가격수익·절댓값및최신가격수익을통제했습니다.</p><p>AT_INFO는가격통제+관심도,AT_PRICE는관심도제거,AT_RAW는관심도만,AT_INV는기본신호의정확한반대입니다. 직전365일·최소300쌍OLS,다음1일라벨완료후추가1일공백. 평균예측이왕복23bp현물롱/13bp선물숏과평균표준오차를넘어야거래합니다. 추가정보는양기간순손익과공통행MSE로판정했고둘다실패했습니다.</p>'''+table(['기간','입력','모형','쌍 수','다음1일 log수익 MSE'],[[p,var,n,x['n'],f"{x['mse']:.8f}" if x['mse'] is not None else '없음'] for p,z in fore.items() for var,models in z.items() for n,x in models.items()],'forecast-results')+'''</section><section><h2>자료 가용성과 비용</h2><p>공식BTC문서조회수2,435일은빈날·0·중복이없고,세다른요청구간21일과정확히일치했습니다. 같은공급자의확인이지모든과거최초배포빈티지복원은아닙니다. day+2일00UTC가용은가정이며추가7일지연도포함했습니다.</p><p>pageview는200/304콘텐츠요청수,앱/web포함·편집/redirect제외입니다. user는고유사람이아니며heuristic봇분류변경과일부자동트래픽이남을수있습니다. 실제IP·개인세션·지갑·사용자내역은수집하지않았습니다.</p><p>현물롱/선물숏, 동시 양다리 없음. 완료20일 변동성 목표20%·명목1배상한·5%p밴드. 현물수수료10bp·선물5bp,각 impact1.5bp,실제funding·종료비용 포함. 기본1h뒤시가/추가1·24h지연,비용2배·위험10%를 모두 보존했습니다. 펀딩 mark는 시간봉시가 대용값이며 호가·부분체결·과거규정·순간청산은 완전 복원하지 못했습니다.</p><p>다수 가설을 이미 검토한 선택편향, 적은 사이클·거래 수, 역사자료 수정과 회귀 불확실성이 남습니다. 매년 수익을 보장하지 않습니다.</p><details><summary>연도별 수익</summary>'''+table(['규칙','기간','2022','2023','2024','2025','2026'],annual,'annual-results')+'</details><details><summary>롱숏·비용·펀딩·노출·변동성</summary>'+table(['규칙','기간','가격손익','비용','펀딩','평균노출%','연변동성%','롱 순손익','숏 순손익'],cost,'cost-results')+'</details><details><summary>대조군 차이의 불확실성</summary><p>14일 블록2,000회95%구간(%/일),7/28일도JSON에 보존.</p>'+table(['규칙','기간','대조','일수익차95%구간'],ci,'uncertainty-results')+'</details></section><section><h2>모든 조건</h2><details id="matrix"><summary>48계좌 전체 보기</summary>'+table(['규칙','기간','조건','수익%','DD%','연변동성%','보유구간','비용'],[[r['strategy'],r['period'],r['scenario'],f"{r['return_pct']:+.2f}",f"{r['max_drawdown_pct']:.2f}",f"{r['realized_vol_pct']:.2f}",r['round_trips'],f"{r['fees']+r['impact']:.2f}"] for r in rows],'all-accounts')+'</details></section>'
 html+='''<section id="proof"><h2>독립 검산과 재현</h2><p>9개미래정보·요일정렬·시각·라벨공백·결측·비용검사. raw329BTC가격/펀딩ZIP,4,747특성창·12,435별도정규방정식예측,20,448판단·4,041폐형식수량·36,945무거래·3,784실제펀딩·7,828이벤트·40,896일말/시간DD를독립검산했습니다.</p><p>예측 최대차9.72×10⁻¹⁷,계좌최대차2×10⁻¹¹ 이내. '''+str(rep['matched_files'])+'''파일 소켓차단 바이트 일치. 구현 검증이지 수익성·실거래 승인이 아닙니다.</p></section><section id="downloads"><h2>검증 자료</h2><div class="downloads"><a download href="downloads/btc-attention-evidence.zip">48계좌·원시조회수·검산 ZIP ↓</a><a download href="downloads/btc-attention-evidence.json">전체 수치·불확실성 JSON ↓</a><a download href="downloads/btc-attention-summary.csv">48조건 CSV ↓</a></div><p>원자료: Wikimedia 공식Bitcoin문서집계조회수. 가격·펀딩 원시 ZIP과 공통 의존성은 별도 재현 자료입니다. <a href="EXPERIMENT_BTC_ATTENTION_20261002.md">성과 전 명세</a> · <a href="BTC_WEB_RESEARCH_20261002.md">검색·원문·실패 기록</a> · <a href="https://doi.org/10.1098/rsif.2014.0623">검토한 논문</a></p><p>연구 목표는 아직 미완료입니다. 정적 페이지는 작업 지속이나 실거래 상태를 보장하지 않습니다.</p></section><footer>BUILD1002a1 · BTC-only · 실거래 없음</footer></main></body></html>'''
 (DOC/'btc-attention-research.html').write_text(html);p=DOC/'btc-web-research.html';old=p.read_text()
 if 'id="attention-followup"' not in old:p.write_text(old.replace('<h1>','<p id="attention-followup" class="boundary">추가48계좌: <a href="btc-attention-research.html">관심도의 추가정보 검증 ↗</a></p><h1>',1))
 files=['btc-attention-research.html','btc-web-research.html','downloads/btc-attention-evidence.zip','downloads/btc-attention-evidence.json','downloads/btc-attention-summary.csv','EXPERIMENT_BTC_ATTENTION_20261002.md','BTC_WEB_RESEARCH_20261002.md','assets/btc-continuation.css','assets/icon.svg'];out=ROOT/'runs/btc-attention-report-20261002';out.mkdir(exist_ok=True);(out/'public-manifest.json').write_bytes(canonical({n:{'sha256':sha((DOC/n).read_bytes()),'bytes':(DOC/n).stat().st_size} for n in files}));print(json.dumps({'accounts':len(rows),'files':len(files)}))
